const raw = $input.first().json;
const parts = raw.candidates?.[0]?.content?.parts || [];
const text = parts.map(p => p.text).filter(Boolean).join('').trim();
if (!text) {
  throw new Error('Gemini не вернул текст промпта. Ответ: ' + JSON.stringify(raw));
}
return [{
  json: {
    scene_description: $('2. Разбить сцены').item.json.scene_description,
    prompt: text
  }
}];

const item = $input.first().json;
const parts = item.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData && p.inlineData.data);
if (!imgPart) {
  throw new Error('Nano Banana не вернул изображение. Ответ: ' + JSON.stringify(item));
}
const buffer = Buffer.from(imgPart.inlineData.data, 'base64');
const mimeType = imgPart.inlineData.mimeType || 'image/png';
const prompt = $('4. Извлечь текст промпта').item.json.prompt;
return [{
  json: { prompt },
  binary: {
    image: await this.helpers.prepareBinaryData(buffer, 'image.png', mimeType)
  }
}];
